import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class ValidationResult:
    valid: bool
    missing_fields: List[str]
    low_confidence_fields: List[str]
    fields: Dict[str, Any]


class TextractExpenseExtractor:
    def __init__(self, region_name: Optional[str] = None):
        self.client = boto3.client("textract", region_name=region_name)

    def extract(self, document_bytes: bytes) -> ValidationResult:
        try:
            response = self.client.analyze_expense(
                Document={"Bytes": document_bytes}
            )
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"Textract analyze_expense failed: {e}") from e

        fields = self._parse_expense_documents(response)
        required_fields = [
            "vendor_name",
            "invoice_receipt_id",
            "invoice_date",
            "total_amount",
            "currency",
        ]

        missing_fields = [f for f in required_fields if not fields.get(f)]
        low_confidence_fields = [
            f for f in required_fields if self._confidence(fields.get(f)) < 0.80
        ]

        return ValidationResult(
            valid=not missing_fields and not low_confidence_fields,
            missing_fields=missing_fields,
            low_confidence_fields=low_confidence_fields,
            fields=fields,
        )

    def _parse_expense_documents(self, response: Dict[str, Any]) -> Dict[str, Any]:
        extracted: Dict[str, Any] = {
            "vendor_name": None,
            "invoice_receipt_id": None,
            "invoice_date": None,
            "total_amount": None,
            "currency": None,
        }

        expense_documents = response.get("ExpenseDocuments", [])
        if not expense_documents:
            return extracted

        summary_fields = expense_documents[0].get("SummaryFields", [])
        for item in summary_fields:
            field_type = (
                item.get("Type", {}).get("Text")
                or item.get("Type", {}).get("Value")
                or ""
            ).upper()
            value = self._summary_field_value(item)
            confidence = self._summary_field_confidence(item)

            if field_type in {"VENDOR_NAME", "SUPPLIER_NAME", "RECEIVER_NAME"} and not extracted["vendor_name"]:
                extracted["vendor_name"] = {
                    "value": value,
                    "confidence": confidence,
                }
            elif field_type in {"INVOICE_RECEIPT_ID", "INVOICE_ID", "DOCUMENT_NUMBER"} and not extracted["invoice_receipt_id"]:
                extracted["invoice_receipt_id"] = {
                    "value": value,
                    "confidence": confidence,
                }
            elif field_type in {"INVOICE_RECEIPT_DATE", "INVOICE_DATE", "ORDER_DATE"} and not extracted["invoice_date"]:
                extracted["invoice_date"] = {
                    "value": value,
                    "confidence": confidence,
                }
            elif field_type in {"TOTAL", "AMOUNT_DUE", "AMOUNT_PAID", "SUBTOTAL"} and not extracted["total_amount"]:
                extracted["total_amount"] = {
                    "value": value,
                    "confidence": confidence,
                }
            elif field_type in {"CURRENCY", "CURRENCY_CODE"} and not extracted["currency"]:
                extracted["currency"] = {
                    "value": value,
                    "confidence": confidence,
                }

        if not extracted["vendor_name"] or not extracted["total_amount"]:
            for line in expense_documents[0].get("LineItemGroups", []):
                for line_item in line.get("LineItems", []):
                    for field in line_item.get("LineItemExpenseFields", []):
                        field_type = (
                            field.get("Type", {}).get("Text")
                            or field.get("Type", {}).get("Value")
                            or ""
                        ).upper()
                        value = self._expense_field_value(field)
                        confidence = self._expense_field_confidence(field)

                        if field_type in {"VENDOR_NAME", "SUPPLIER_NAME"} and not extracted["vendor_name"]:
                            extracted["vendor_name"] = {
                                "value": value,
                                "confidence": confidence,
                            }
                        elif field_type in {"TOTAL", "AMOUNT_DUE"} and not extracted["total_amount"]:
                            extracted["total_amount"] = {
                                "value": value,
                                "confidence": confidence,
                            }

        return extracted

    def _summary_field_value(self, item: Dict[str, Any]) -> Any:
        return (
            item.get("ValueDetection", {}).get("Text")
            or item.get("ValueDetection", {}).get("Value")
            or item.get("LabelDetection", {}).get("Text")
            or item.get("LabelDetection", {}).get("Value")
        )

    def _summary_field_confidence(self, item: Dict[str, Any]) -> float:
        return float(
            item.get("ValueDetection", {}).get("Confidence")
            or item.get("LabelDetection", {}).get("Confidence")
            or 0.0
        )

    def _expense_field_value(self, item: Dict[str, Any]) -> Any:
        return (
            item.get("ValueDetection", {}).get("Text")
            or item.get("ValueDetection", {}).get("Value")
        )

    def _expense_field_confidence(self, item: Dict[str, Any]) -> float:
        return float(item.get("ValueDetection", {}).get("Confidence") or 0.0)

    def _confidence(self, field_entry: Any) -> float:
        if not field_entry:
            return 0.0
        if isinstance(field_entry, dict):
            return float(field_entry.get("confidence") or 0.0)
        return 0.0


def extract_and_validate_document(document_bytes: bytes, region_name: Optional[str] = None) -> Dict[str, Any]:
    extractor = TextractExpenseExtractor(region_name=region_name)
    result = extractor.extract(document_bytes)

    normalized_fields = {
        key: (value["value"] if isinstance(value, dict) else value)
        for key, value in result.fields.items()
    }

    confidences = {
        key: (value["confidence"] if isinstance(value, dict) else 0.0)
        for key, value in result.fields.items()
    }

    return {
        "valid": result.valid,
        "missing_fields": result.missing_fields,
        "low_confidence_fields": result.low_confidence_fields,
        "fields": normalized_fields,
        "confidences": confidences,
    }
